class Solution { public int[] recoverArray(int[] nums){Arrays.sort(nums);int half=nums.length/2;for(int candidate=1;candidate<nums.length;candidate++){int gap=nums[candidate]-nums[0];if(gap<=0||(gap&1)==1)continue;TreeMap<Integer,Integer> count=new TreeMap<>();for(int value:nums)count.merge(value,1,Integer::sum);int[] answer=new int[half];int size=0;boolean valid=true;for(int low:nums){int remaining=count.getOrDefault(low,0);if(remaining==0)continue;int high=low+gap;if(count.getOrDefault(high,0)==0){valid=false;break;}decrease(count,low);decrease(count,high);answer[size++]=low+gap/2;}if(valid&&size==half)return answer;}return new int[0];}private void decrease(Map<Integer,Integer> count,int value){int next=count.get(value)-1;if(next==0)count.remove(value);else count.put(value,next);} }
